async function getUser(id) {
  const response = await fetch(`/api/users/${id}`);

  if (!response.ok) {
    // This check is REQUIRED - fetch() alone won't throw for a 404!
    throw new Error(`Request failed: ${response.status}`);
  }

  return response.json();
}

